\begin{theorem}[Quantum soundness of the simultaneous classical low-degree test]
  \label{lem:ld-soundness}
  There exists a function $\delta_{\ld}(\eps, q, m, d, \ldc) = a (dm \ldc)^a (\eps^b + q^{-b} + 2^{-bmd})$ for universal constants $a\geq 1$ and $0<b\leq 1$ 
such that the following
  holds.
  For all $\eps > 0$ and parameter tuple $\ldparams = (q, m, d, \ldc)$, for all
  projective strategies $(\psi,A,B)$ that succeed with probability at least
  $1-\eps$ in the game $\game^\ld_\ldparams$, there exists measurements
  \[G^w \in \simulpolymeas{m}{d}{q}{\ldc}\] on $\mH_w$, for
  $w\in\{\alice,\bob\}$, such that
  \begin{equation*}
    \begin{split}
      A^{\Point,\, u}_{a_1,\, a_2,\, \ldots\,,\, a_\ldc}
      & \abc[\delta_{\ld}]
      G^\bob_{[(g_1(u),g_2(u),\ldots,g_\ldc(u)) = (a_1,\, a_2,\, \ldots \,,\, a_\ldc)]}\;,\\
      G^\alice_{[(g_1(u),g_2(u),\ldots,g_\ldc(u)) = (a_1,\, a_2,\, \ldots \,,\, a_\ldc)]}
      & \abc[\delta_{\ld}]
			 B^{\Point,\, u}_{a_1,\, a_2,\, \ldots\,,\, a_\ldc}\;,\\
      G^\alice_{g_1,\, g_2,\, \ldots \,,\, g_\ldc}
      & \abc[\delta_{\ld}]
      G^\bob_{g_1,\, g_2,\, \ldots \,,\, g_\ldc}\;,
    \end{split}
  \end{equation*}
  where $\delta_{\ld} = \delta_{\ld}(\eps, q, m, d, \ldc)$, 
  and all three statements are with respect to the state $\ket{\psi}$.
In addition, the first two approximations hold under the uniform distribution over $u\in \F_q^m$,
	whereas there is no question distribution associated with the third approximation.
\end{theorem}

\begin{proof}
Let $\ldparams = (q, m, d, \ldc)$
where $m, d, \ldc \in \N$ are integers, $q \in \N$ is an admissible field size,
and $m$ divides $q$. Let $\Sigma=\F_q$. Let $\code \subseteq \Sigma^q$ be the Reed-Solomon code with degree $d$. Explicitly, $\code$ is the set of all $(p(x_1),\ldots,p(x_n))$ where $p:\F_q\to\F_q$ is a univariate polynomial of degree at most $d$ and $x_1,\ldots,x_n$ are an enumeration of $\F_q$. Then in the (standard) notation from~\cite{ji2021quantum} $\code$ is a linear $[q,d+1,n-d+1]_\Sigma$ code.

Observe that the two-prover tensor code test, for the code $\code^{\otimes m}$, as described in~\cite[Figure 1 and Figure 2]{ji2021quantum}, is identical to the game $\game^\ld$ with parameters $\ldparams$ and $\ldc=1$, whose decider is presented in Figure~\ref{fig:ld-decider}. This is because 
\begin{enumerate}
\item The \emph{axis-parallel line-versus-point test} from Figure~\ref{fig:ld-decider} is identical to the \emph{axis-parallel lines test} from~\cite[Figure 1]{ji2021quantum}, with the only difference that in Figure~\ref{fig:ld-decider} the roles of A and B are chosen uniformly at random. This is consistent with the two-prover variant of the tensor code test from~\cite[Section 4.1]{ji2021quantum}.
\item The \emph{diagonal line-versus-point test} from Figure~\ref{fig:ld-decider} is identical to the \emph{subcube commutation test} from~\cite[Figure 1]{ji2021quantum}, with again the added symmetrization between players. 
\item The \emph{consistency test} from Figure~\ref{fig:ld-decider} is identical to the \emph{synchronicity test} from~\cite[Figure 2]{ji2021quantum}.
\end{enumerate}

As a result,~\cite[Theorem 4.7]{ji2021quantum}, in which we choose the parameter $k$ as $k=m^3d$,  immediately yields \Cref{lem:ld-soundness}.

To conclude it remains to extend the result to the case of general $\ldc$. This is done 
via a standard reduction, following exactly the same steps as the derivation of Theorem 4.43 from Theorem 4.40 in~\cite{NW19}.
\end{proof}

\begin{theorem}[Main theorem; quantum soundness of the low individual degree test]\label{thm:main-formal}
  Consider a projective strategy $(\psi, A^{\mathrm{A}},B^{\mathrm{A}},L^{\mathrm{A}},A^{\mathrm{B}},B^{\mathrm{B}},L^{\mathrm{B}})$ 
   which passes the  $(m,q,d)$-low individual degree test with probability at least $1-\eps$.
  Let $k \geq md$ be an integer.
  Let
  \begin{equation*}
  \nu = 100000 k^2m^4 \cdot \Big(\eps^{1/40000} + (d/q)^{1/40000} + e^{-k/(2560000m^2)}\Big).
  \end{equation*}
Then there exists projective measurements $G^{\mathrm{A}}, G^{\mathrm{B}} \in \polymeas{m}{q}{d}$ with the following properties:
\begin{enumerate}
  \item (Consistency with~$A$):  On average over $\bu \sim \F_q^{m}$,
	  \begin{align*}
	  A^{\mathrm{A},u}_a \otimes I
	  	&\simeq_{\nu} I \otimes G^{\mathrm{B}}_{[g(u)=a]},\\
	I \otimes A^{\mathrm{B},u}_a
	  	&\simeq_{\nu}  G^{\mathrm{A}}_{[g(u)=a]} \ot I.
	  \end{align*}
\item (Self-consistency):
	\begin{equation*}
	G^{\mathrm{A}}_g \ot I \simeq_{\nu} I \ot G^{\mathrm{B}}_g.
	\end{equation*}
\end{enumerate}
\end{theorem}

We note that there is a tradeoff in \Cref{thm:main-formal} specified by the parameter~$k$.
\begin{lemma}\label{lem:alnf}
	\lean{MIPStarRE.QPBT.aLinePointDist_point_marginal_uniform, MIPStarRE.QPBT.aLinePointDist_mem_line}
	\leanok
	\uses{def:line-point-dist, def:line}
	Consider the pair $(\ell, u)$ sampled in the following way: first, sample the tuple $\bigl((u_0,s,0),(u,0,0)\bigr)$ from the CL distribution $\mu_{L_{\mathsf{ALine}}, L_{\mathsf{Point}}}$, and let $\ell = \ell(u_0, e_i)$ where $i = \chi(s)$. Then $u$ is a uniformly random point in $\F_q^m$, and $\ell$ is a line that goes through $u$ and is parallel to a uniformly random axis $i \in \{1,2,\ldots,m\}$.
\end{lemma}
\begin{proof}
	\leanok
	\uses{def:cl-dist, def:ld-question-distribution, def:ld-line-description, def:line-representative, lem:distribution-map-comp, lem:uniform-map-equivalence, lem:uniform-product-first-marginal, lem:uniform-product-second-marginal, lem:chi-index-uniform, lem:line-representative-idempotent, lem:line-rep-incidence}
	By Definition~\ref{def:cl-dist} the distribution $\mu_{L_{\mathsf{ALine}}, L_{\mathsf{Point}}}$ is the push-forward of the uniform distribution on $V$ along $z \mapsto \bigl(L_{\mathsf{ALine}}(z), L_{\mathsf{Point}}(z)\bigr)$, so each marginal below is the push-forward of the uniform distribution on $V$ along the composite of that map with the corresponding coordinate. The point marginal is the image of the uniform distribution on $V$ under $(u,s,v) \mapsto u$, hence uniform on $\F_q^m$. The axis marginal is its image under $(u,s,v) \mapsto \chi(s)$; since $m$ divides $q$, every fibre of $\chi$ has exactly $q/m$ elements, so $i = \chi(s)$ is uniform on $\{1,2,\ldots,m\}$ and $(u_0,s)$ specifies a uniformly random axis-parallel line $\ell(u_0,e_i)$. Finally the base point recorded in the sample is $u_0 = L^{\mathrm{Ln}}_{e_i}(u)$, which is fixed by $L^{\mathrm{Ln}}_{e_i}$ (Definition~\ref{def:line-representative}) and satisfies $u \in \ell(u_0,e_i)$ by Lemma~\ref{lem:line-rep-incidence}.
\end{proof}

\begin{lemma}\label{lem:dlnf}
